package com.bank.compute;

import java.util.logging.Logger;

// Long-lived, shared, interactive. Stays up (and bills) until idle timeout.
class AllPurposeCluster {
    private static final Logger log = Logger.getLogger(AllPurposeCluster.class.getName());

    private boolean running = false;
    private double billedMinutes = 0;

    void startIfNeeded() {
        if (!running) { running = true; log.info("All-Purpose cluster started (shared, interactive)"); }
    }

    double run(Workload w) {
        startIfNeeded();
        double minutes = w.workUnits / 10.0;
        billedMinutes += minutes;
        log.info(() -> "All-Purpose ran '" + w.name + "' for " + minutes + " min, shared by "
                + w.concurrentUsers + " users (stays up after)");
        return minutes;
    }

    // Idle time keeps billing until auto-termination.
    void idle(double idleMinutes, int autoTerminate) {
        billedMinutes += Math.min(idleMinutes, autoTerminate); // billed until it terminates
        if (idleMinutes >= autoTerminate) { running = false;
            log.info(() -> "All-Purpose auto-terminated after " + autoTerminate + " idle min (but idle time WAS billed)"); }
    }

    double billedMinutes() { return billedMinutes; }
}
