package com.bank.compute;

import java.util.logging.Logger;

// Ephemeral: created for ONE run, terminated immediately after. No idle cost.
class JobCluster {
    private static final Logger log = Logger.getLogger(JobCluster.class.getName());

    private double billedMinutes = 0;

    double runOnce(Workload w) {
        double startup = 2.0; // per-run startup (reduced by cluster pools)
        double runtime = w.workUnits / 12.0; // isolated, often slightly faster (no noisy neighbors)
        double total = startup + runtime;
        billedMinutes += total;
        log.info(() -> "Job cluster created → ran '" + w.name + "' in " + runtime
                + " min (+" + startup + " startup) → terminated. NO idle cost.");
        return total;
    }

    double billedMinutes() { return billedMinutes; }
}
