package com.bank.compute;

import java.util.logging.Logger;

// SQL endpoint tuned for concurrent SQL/BI. Serverless starts in seconds.
class SqlWarehouse {
    private static final Logger log = Logger.getLogger(SqlWarehouse.class.getName());

    private final boolean serverless;
    private double billedMinutes = 0;

    SqlWarehouse(boolean serverless) { this.serverless = serverless; }

    double serveQueries(Workload w) {
        double startup = serverless ? 0.1 : 3.0; // serverless ~instant, classic needs cluster start
        double runtime = w.workUnits / 20.0;      // Photon-tuned for SQL, scales concurrency
        double total = startup + runtime;
        billedMinutes += total;
        log.info(() -> "SQL Warehouse (" + (serverless ? "serverless" : "classic") + ") served '"
                + w.name + "' for " + w.concurrentUsers + " users in " + runtime
                + " min (+" + startup + " start)");
        return total;
    }

    double billedMinutes() { return billedMinutes; }
}
