package com.bank.compute;

import java.util.logging.Logger;

// Routes each workload to the correct compute type.
class ComputeRouter {
    private static final Logger log = Logger.getLogger(ComputeRouter.class.getName());

    private final AllPurposeCluster allPurpose;
    private final SqlWarehouse warehouse;

    ComputeRouter(AllPurposeCluster allPurpose, SqlWarehouse warehouse) {
        this.allPurpose = allPurpose;
        this.warehouse = warehouse;
    }

    void route(Workload w) {
        switch (w.kind) {
            case INTERACTIVE_DEV -> { log.info(() -> "Route '" + w.name + "' → All-Purpose cluster"); allPurpose.run(w); }
            case PRODUCTION_JOB  -> { log.info(() -> "Route '" + w.name + "' → ephemeral Job cluster"); new JobCluster().runOnce(w); }
            case SQL_ANALYTICS   -> { log.info(() -> "Route '" + w.name + "' → SQL Warehouse"); warehouse.serveQueries(w); }
        }
    }
}
