package com.bank.compute;

import java.util.logging.Logger;

public class ComputeDemo {
    private static final Logger log = Logger.getLogger(ComputeDemo.class.getName());

    public static void main(String[] args) {
        AllPurposeCluster allPurpose = new AllPurposeCluster();
        SqlWarehouse warehouse = new SqlWarehouse(true); // serverless
        ComputeRouter router = new ComputeRouter(allPurpose, warehouse);

        // Developer exploration during the day → All-Purpose.
        router.route(new Workload("explore_trade_features", Workload.Kind.INTERACTIVE_DEV, 50, 3));
        allPurpose.idle(30, 30); // sits idle, billed until auto-terminate

        // Nightly production ETL → ephemeral Job cluster (isolated, no idle cost).
        router.route(new Workload("nightly_trade_etl", Workload.Kind.PRODUCTION_JOB, 400, 0));

        // Morning BI burst → serverless SQL Warehouse (instant start, concurrency).
        router.route(new Workload("morning_dashboards", Workload.Kind.SQL_ANALYTICS, 120, 40));

        log.info(() -> "Billed — AllPurpose=" + allPurpose.billedMinutes()
                + " min, SqlWarehouse=" + warehouse.billedMinutes() + " min");
        log.warning("If ALL of this ran on one always-on All-Purpose cluster, idle+collision cost would be far higher");
    }
}
